import os
from alibabacloud_green import Client as GreenClient

def moderate_messages(messages):
    """Moderate a batch of messages using Alibaba Content Moderation.

    Returns a list of dictionaries with moderation decisions for each message.
    """
    client = GreenClient(
        access_key_id=os.getenv('ALIBABA_CLOUD_ACCESS_KEY_ID'),
        access_key_secret=os.getenv('ALIBABA_CLOUD_ACCESS_KEY_SECRET')
    )

    decisions = []
    for message in messages:
        request = {
            'method': 'POST',
            'uri': '/green/text/scan',
            'query': {},
            'body': {
                'tasks': [
                    {
                        'dataId': f"{message}",
                        'content': message,
                        'scenes': ['antispam']
                    }
                ]
            }
        }
        response = client.request(request)

        decision = {
            'message': message,
            'spammer': response['data']['results'][0]['labels'][0]['label'] == 'spam'
        }
        decisions.append(decision)

    return decisions
